import{_ as a,o as l,c as s,a3 as o}from"./chunks/framework.B7pF4b99.js";const u=JSON.parse('{"title":"Spec 30：桌面 Terminal 與圖形 shell","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-30-graphical-terminal.md","filePath":"SPEC-30-graphical-terminal.md","lastUpdated":1793864111000}'),r={name:"SPEC-30-graphical-terminal.md"};function n(i,e,c,t,d,p){return l(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="spec-30-桌面-terminal-與圖形-shell" tabindex="-1">Spec 30：桌面 Terminal 與圖形 shell <a class="header-anchor" href="#spec-30-桌面-terminal-與圖形-shell" aria-label="Permalink to &quot;Spec 30：桌面 Terminal 與圖形 shell&quot;">​</a></h1><p>日期：2026-11-02</p><p>狀態：已實作並完成 QEMU 互動驗收；有限終端子集</p><h2 id="目標" tabindex="-1">目標 <a class="header-anchor" href="#目標" aria-label="Permalink to &quot;目標&quot;">​</a></h2><ul><li>保留 <code>make run</code> 的 UART shell；在既有 1280×720 圖形桌面左上放置 Terminal 圖示。</li><li>使用 VirtIO tablet 點擊圖示開啟固定大小終端視窗，並以真正的 VirtIO keyboard 操作既有 <code>user.elf</code> shell。</li><li>GUI 輸入、shell 輸出、行編輯與 ANSI 畫面更新均在 guest kernel/guest process 中完成；QEMU VNC 只呈現 guest framebuffer。</li></ul><h2 id="範圍與限制" tabindex="-1">範圍與限制 <a class="header-anchor" href="#範圍與限制" aria-label="Permalink to &quot;範圍與限制&quot;">​</a></h2><ul><li>僅新增一個固定位置、固定大小、可關閉/重新顯示的 Terminal 視窗；不做一般視窗管理、拖曳、縮放、工作列或 file manager。</li><li>Terminal 使用單一自訂 kernel TTY/PTY 子集，不宣稱 POSIX <code>openpty</code> 或完整 <code>termios</code>。</li><li>虛擬鍵盤支援 US ASCII、左右 Shift/Ctrl、Enter、Backspace、Tab、Ctrl-D、方向鍵；滑鼠只需絕對定位與左鍵。</li><li>字元終端為 100×30；支援 CR/LF/Backspace/Tab、自動換行/捲動、CSI <code>H/f A/B/C/D J K m</code>、SGR 基本色/亮色/反白、私有 <code>?25</code>、<code>?1049h/l</code>。</li><li>不新增測試程式碼；不修改 <code>AGENTS.md</code>、既有 <code>tools/__pycache__</code> 或原始 WUFS/swap 映像。</li><li>不支援視窗拖曳/縮放、剪貼簿、job control、Ctrl+C、完整 POSIX PTY/termios 或多視窗。</li></ul><h2 id="架構" tabindex="-1">架構 <a class="header-anchor" href="#架構" aria-label="Permalink to &quot;架構&quot;">​</a></h2><h3 id="概念與目前實作" tabindex="-1">概念與目前實作 <a class="header-anchor" href="#概念與目前實作" aria-label="Permalink to &quot;概念與目前實作&quot;">​</a></h3><ul><li>教科書概念：I/O 子系統可把裝置事件與上層使用者介面分層；行程生命週期由 parent、exit 與 reaping 串接。參考 <code>notes/ch12 I_O Systems.md</code> 與 <code>notes/ch3 Process.md</code>。</li><li>WUWAOS 實作：本階段只有一個由 VirtIO keyboard/tablet 驅動的自訂 GUI TTY，並重用既有 shell、process 與 FD 路徑；不實作教科書以外的 POSIX PTY/termios ABI。</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>QEMU VirtIO keyboard/tablet</span></span>
<span class="line"><span>  → FDT + device config 能力辨識</span></span>
<span class="line"><span>  → kernel event queue（按 SYN_REPORT 提交整批事件）</span></span>
<span class="line"><span>  → desktop hit-test / US key mapping</span></span>
<span class="line"><span>  → GUI TTY input ring → 已聚焦 Terminal shell 的 fd 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GUI shell fd 1/2 → kernel TTY output ring → ANSI VT parser</span></span>
<span class="line"><span>  → terminal cell buffer → desktop framebuffer compositor → VirtIO GPU</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><ul><li>Tablet 與 keyboard 由 FDT 掃描辨識，不依賴 VirtIO MMIO slot 順序；兩者仍使用 supervisor-only MMIO mapping。GUI Make targets 共用 QEMU 裝置 recipe，<code>make run</code> 不增加 GUI 裝置。</li><li>GUI shell 由 scheduler 可安全呼叫的專用 process helper 建立，父 PID 為 0、stdin/out/err 綁 GUI TTY endpoints。不可在 <code>current_index == -1</code> 時呼叫依賴 <code>process_current()</code> 的一般 syscall helper。視窗關閉僅隱藏並保留單一 session；圖示重新顯示同一 session。shell 執行 <code>exit</code> 後沿既有 parent=0 Zombie reaper 路徑回收 process/raw owner/FD，圖示下次點擊才建立新 shell。</li><li>GUI TTY 與 UART console 分開輸入佇列、raw owner 與 CR/LF 狀態；canonical 模式在 Enter 後交付一行，Backspace 編輯目前輸入，Ctrl-D 在空行回傳 EOF；raw 模式交付單一 byte，交由 fan/workstate 自行處理 ANSI/按鍵。輸入只送到目前可見且聚焦的 GUI shell。輸出 ring 有固定容量，滿載時先排空至 VT parser 再繼續；GUI shell 阻塞時 scheduler 持續 poll，不在 desktop event callback 同步等待。</li><li>kernel boot/driver/scheduler diagnostics 維持 UART。一般 user write 由 GUI shell FD 直接寫 GUI TTY；<code>ps</code>/<code>pcb</code>/<code>vmstat</code> 內建 syscall 只在呼叫其核心列印函式的短區間暫時路由，readline echo 依輸入端點寫回同一 TTY。其他 syscall、exec/exit 與可能掛起的呼叫不持有此路由狀態。</li><li>Window 採 8×16 ASCII bitmap 字元格，至少完整繪製 <code>0x20–0x7e</code>；標題列有關閉按鈕、terminal 有可見游標。Terminal buffer 與桌布分層合成，重繪以 dirty region 批次提交，需保存/還原鼠標下方最終合成像素，確保游標移動不留下殘影。</li><li>VT parser 有普通螢幕與 alternate screen 兩套 cell/cursor 狀態；<code>?1049h/l</code> 切換時保存/還原普通內容。SGR 支援 reset、bold、反白、基本前景/背景色與亮色；不支援的 CSI 安全忽略，不會送入 TTY/檔案資料流。</li></ul><h2 id="步驟與驗收條件" tabindex="-1">步驟與驗收條件 <a class="header-anchor" href="#步驟與驗收條件" aria-label="Permalink to &quot;步驟與驗收條件&quot;">​</a></h2><ol><li>檢查並記錄原 UART、GUI、磁碟路徑；完成鍵盤/tablet probe、事件 queue、按鍵/點擊事件。</li><li>加入 desktop icon/window、ASCII 字型、ANSI cell parser、cursor 合成及批次 dirty rendering。</li><li>接上獨立 GUI TTY endpoint、process 建立/回收、FD fork/dup/exec/close 傳遞、raw/cooked/EOF 與 shell/kernel command output routing。</li><li>更新 Makefile GUI 裝置參數、README、程式碼導覽、網站首頁及開機/應用主題；不將 OS source 複製到網站。</li><li>WSL Ubuntu 執行 <code>make -j2</code> 通過。直接啟動 QEMU <code>-snapshot</code>（VirtIO GPU/tablet/keyboard、WUFS 與 4095-slot swap），以 QMP <code>input-send-event</code> 實際點擊圖示與送鍵、<code>screendump</code> 留存 guest framebuffer。驗收 <code>help</code>、<code>echo</code>、<code>pwd</code>、<code>ls</code>、Backspace、<code>echo hello | cat</code>、<code>write</code>/<code>cat</code>、<code>fan</code> 編輯/存檔/退出、<code>workstate</code> 的 <code>q</code> 返回、<code>ps</code>/<code>vmstat</code> GUI 輸出、關閉/重開、Ctrl-D 結束 shell 與重建。圖片為 <a href="./images/wuwaos-terminal.png">GUI shell</a> 及 <a href="./images/wuwaos-terminal-workstate.png">workstate</a>。</li><li>不帶 GPU/tablet/keyboard 的 <code>-nographic -snapshot</code> 實際執行 <code>help</code> 與 <code>echo uart-regression</code>，UART shell 正常。原始 <code>build/wuwaos.img</code> 和 <code>build/wuwaos-swap.img</code> 在 snapshot 前後 SHA-256 相同，guest 寫入只在 snapshot overlay。核心連結結尾 <code>0x80320000</code>，低於 <code>0x80400000</code> 上界；使用者 shell text 為 16310 bytes，低於 16 KiB 限制。沒有新增測試程式碼。</li></ol><h2 id="實作限制與未驗收項目" tabindex="-1">實作限制與未驗收項目 <a class="header-anchor" href="#實作限制與未驗收項目" aria-label="Permalink to &quot;實作限制與未驗收項目&quot;">​</a></h2><ul><li>驗收使用 QEMU 8.2.2 WSL Ubuntu、1280×720 VNC framebuffer、QMP 輸入事件；尚未在實體 RISC-V 硬體或其他 QEMU 顯示器驗證。</li><li>已分別驗證 snapshot GUI 與無圖形裝置的 UART shell；未在同一個 VM 同時向 GUI raw app 與 UART shell 送輸入，因此兩端同時工作的隔離未動態驗證。</li><li>不支援功能如上列範圍；未逐一動態驗證不支援/錯誤 ANSI CSI、queue 滿載、行輸入容量滿載、process table/memory 耗盡與 VirtIO 裝置故障。</li><li>輸入字元限 US ASCII；沒有 composition、Unicode、剪貼簿、視窗拖曳/縮放、背景工作控制或 Ctrl+C。Terminal 標題列的 X 只隱藏視窗；使用 launcher 時關閉 VNC viewer 會停止整個 QEMU session。結束 shell 請使用 <code>exit</code> 或空行 Ctrl-D。</li></ul><h2 id="移除視窗硬陰影" tabindex="-1">移除視窗硬陰影 <a class="header-anchor" href="#移除視窗硬陰影" aria-label="Permalink to &quot;移除視窗硬陰影&quot;">​</a></h2><p>日期：2026-11-05。狀態：原始碼已修改，編譯及 QEMU 互動驗收待記錄。</p><p>原視窗繪製會先在右移 6、下移 8 像素的位置畫深色實心矩形，再繪製視窗本體，因此右側與下側看起來多出一層邊。這是 guest 的繪製邏輯，不是半透明或模糊陰影。</p><p>目前原始碼已移除這個矩形，並將開窗、關窗、焦點切換、終端輸出與滑鼠重繪使用的區域統一為視窗本體寬高。驗收時需確認右／下深色邊消失，以及滑鼠跨越邊界、關閉與重新顯示視窗後沒有殘影。</p><p>本節不覆寫上面的歷史 QEMU 驗收結果。既有截圖與 portable v1 ZIP 仍保留先前的視窗外觀，網站更新不代表本次核心修正已驗收或重新發布。</p>`,21)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
